#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Higienização PBIP — Remoção Automatizada de Objetos Não Utilizados

Executa o processo completo de higienização de um projeto Power BI (PBIP):
1. Analisa uso de objetos (colunas, colunas calculadas, medidas) no modelo e relatório
2. Identifica objetos com StatusFinal = "Não utilizada"
3. Remove esses objetos dos arquivos .tmdl
4. Remove tabelas inteiras se ficarem vazias
5. Atualiza relationships.tmdl e model.tmdl
6. Copia estrutura PBIP para nova pasta com sufixo _higienizado
7. Gera RELATORIO_HIGIENIZACAO.md com detalhamento

Uso:
    python higienizacao_pbip.py                # usa pasta atual
    python higienizacao_pbip.py --root /caminho # especifica raiz do projeto
    python higienizacao_pbip.py --dry-run       # apenas simula, não escreve

Critério de remoção: APENAS StatusFinal = "Não utilizada" (não "Cadeia sem uso real").
"""

from __future__ import annotations

import argparse
import os
import re
import json
import shutil
from datetime import datetime
from collections import defaultdict
from pathlib import Path
from typing import List, Dict, Set, Tuple, Optional, Any


# ==================== CONFIGURAÇÃO ====================

# Colunas referenciadas na partição M do stgFuncionarios
# (extraídas do M query — Table.TransformColumnTypes, Table.AddColumn, etc.)
STG_COLUNAS_OBRIGATORIAS = {
    "ID RH", "Nome Completo", "Estado Civil", "Sexo", "Data de Nascimento",
    "Endereço", "Data de Contratacao", "Data de Demissao", "Salario Base",
    "Impostos", "Beneficios", "VT", "VR", "Cargo", "Nível", "Área",
    "Ferias Acumuladas", "Horas Extras", "Imagem", "Avaliação do Funcionário",
    "Trabalho em Equipe", "Liderança", "Comunicação", "Iniciativa", "Organização",
    # Flags criadas no M query:
    "Flag Data Demissão Antes Contratação", "Flag Valor Financeiro Negativo",
    "Flag Férias Negativas", "Flag Horas Extras Negativas",
    "Flag Avaliação Fora 0 a 10", "Flag Competência Fora 0 a 10",
    "Flag Idade Admissão Menor 18", "Flag Registro Inválido",
}

# Tabelas de data: preservar colunas obrigatórias
TABELAS_DATA_PREFIXOS = ["dCalendario", "DateTableTemplate_", "LocalDateTable_"]
COLUNAS_DATA_OBRIGATORIAS = {"Date", "Hierarquia de datas", "MonthNo", "QuarterNo"}


def is_data_table(table_name: str) -> bool:
    """Verifica se uma tabela é tabela de data auto-gerada."""
    return any(table_name.startswith(p) for p in TABELAS_DATA_PREFIXOS)


# ==================== FUNÇÕES UTILITÁRIAS ====================

def read_text_file(path: str) -> str:
    """Lê arquivo tentando utf-8-sig e utf-8."""
    for enc in ("utf-8-sig", "utf-8"):
        try:
            with open(path, "r", encoding=enc, errors="strict") as f:
                return f.read()
        except UnicodeDecodeError:
            continue
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()


def find_object_blocks(tmdl_text: str, object_type: str) -> List[Dict[str, Any]]:
    """
    Encontra blocos de objetos (column/measure) no texto TMDL.
    Retorna lista de dicts: {name, start_line, end_line, block_text, indent_level}
    """
    blocks = []
    lines = tmdl_text.split("\n")

    if object_type == "column":
        # Aceita: column Nome  |  column 'Nome'  |  column Nome = expressão  |  column 'Nome' = expressão
        pattern = re.compile(r"^(\t*)column\s+(?:'([^']+)'|(\S+))\s*(=\s*.*)?$")
    elif object_type == "measure":
        pattern = re.compile(r"^(\t*)measure\s+(?:'([^']+)'|(\S+))\s*=")
    else:
        raise ValueError(f"object_type deve ser 'column' ou 'measure', recebido: {object_type}")

    i = 0
    while i < len(lines):
        m = pattern.match(lines[i])
        if m:
            indent = len(m.group(1))
            name = m.group(2) or m.group(3)
            start_line = i

            # Encontrar fim do bloco: próxima linha com indentação <= indent que começa novo objeto
            j = i + 1
            while j < len(lines):
                line = lines[j]
                stripped = line.strip()

                if stripped == "":
                    j += 1
                    continue

                curr_indent = len(line) - len(line.lstrip("\t"))

                # Fim do bloco: indentação menor ou igual E começa novo elemento estrutural
                if curr_indent <= indent and (
                    re.match(r"^(column|measure|partition|annotation)\b", stripped)
                    or re.match(r"^[A-Za-z]+\s*:", stripped)
                    or stripped.startswith("///")
                ):
                    break
                j += 1

            end_line = j
            block_text = "\n".join(lines[start_line:end_line])
            blocks.append({
                "name": name,
                "start_line": start_line,
                "end_line": end_line,
                "block_text": block_text,
                "indent_level": indent,
            })
            i = j
        else:
            i += 1

    return blocks


def extract_expression(block_text: str, object_type: str) -> str:
    """Extrai a expressão DAX de um bloco measure ou column calculada."""
    lines = block_text.split("\n")
    expr_parts = []
    in_expr = False

    for line in lines:
        stripped = line.strip()
        if not in_expr:
            if object_type == "measure" and "=" in stripped and stripped.startswith("measure"):
                after_eq = stripped.split("=", 1)[1].strip()
                if after_eq:
                    expr_parts.append(after_eq)
                in_expr = True
            elif object_type == "column" and "=" in stripped and stripped.startswith("column"):
                after_eq = stripped.split("=", 1)[1].strip()
                if after_eq:
                    expr_parts.append(after_eq)
                in_expr = True
        else:
            if re.match(
                r"^(formatString|displayFolder|lineageTag|isHidden|annotation|"
                r"changedProperty|dataCategory|dataType|summarizeBy|sourceColumn|"
                r"isUnique|isNameInferred|variation|sortByColumn)\b",
                stripped,
            ):
                break
            if stripped:
                expr_parts.append(stripped)

    return " ".join(expr_parts)


def remove_blocks_from_text(tmdl_text: str, blocks_to_remove: List[Dict]) -> str:
    """Remove blocos do texto TMDL. Retorna texto limpo."""
    if not blocks_to_remove:
        return tmdl_text

    lines = tmdl_text.split("\n")
    sorted_blocks = sorted(blocks_to_remove, key=lambda b: b["start_line"], reverse=True)

    for block in sorted_blocks:
        del lines[block["start_line"]:block["end_line"]]

    return "\n".join(lines)


def is_table_empty(tmdl_text: str) -> bool:
    """Verifica se uma tabela TMDL não tem colunas, medidas ou partições."""
    cols = find_object_blocks(tmdl_text, "column")
    meas = find_object_blocks(tmdl_text, "measure")
    has_partition = bool(re.search(r"^(\t*)partition\s+", tmdl_text, re.MULTILINE))
    return len(cols) == 0 and len(meas) == 0 and not has_partition


def parse_table_col(ref: str) -> Tuple[str, str]:
    """Parseia referência Tabela.Coluna (com ou sem aspas)."""
    ref_clean = ref.strip().replace("'", "")
    parts = ref_clean.split(".", 1)
    if len(parts) == 2:
        return parts[0].strip(), parts[1].strip()
    return ref_clean, ""


# ==================== ETAPA 1: EXTRAÇÃO DE OBJETOS ====================

def extrair_objetos(tables_dir: Path):
    """Varre arquivos .tmdl e extrai catálogo de objetos."""
    objetos = []
    tabelas_info = {}

    for tmdl_path in sorted(tables_dir.glob("*.tmdl")):
        table_name = tmdl_path.stem
        tmdl_text = read_text_file(str(tmdl_path))

        tabelas_info[table_name] = {
            "file_path": str(tmdl_path),
            "tmdl_text": tmdl_text,
            "columns": [],
            "measures": [],
        }

        # Colunas
        for block in find_object_blocks(tmdl_text, "column"):
            is_calculated = "=" in block["block_text"].split("\n")[0]
            tipo = "Coluna Calculada" if is_calculated else "Coluna"
            expr = extract_expression(block["block_text"], "column")
            obj = {
                "table": table_name,
                "name": block["name"],
                "tipo": tipo,
                "expression": expr,
                "block_text": block["block_text"],
                "start_line": block["start_line"],
                "end_line": block["end_line"],
            }
            objetos.append(obj)
            tabelas_info[table_name]["columns"].append(obj)

        # Medidas
        for block in find_object_blocks(tmdl_text, "measure"):
            expr = extract_expression(block["block_text"], "measure")
            obj = {
                "table": table_name,
                "name": block["name"],
                "tipo": "Medida",
                "expression": expr,
                "block_text": block["block_text"],
                "start_line": block["start_line"],
                "end_line": block["end_line"],
            }
            objetos.append(obj)
            tabelas_info[table_name]["measures"].append(obj)

    return objetos, tabelas_info


# ==================== ETAPA 2: DEPENDÊNCIAS DAX ====================

def analisar_dependencias(objetos: List[Dict]):
    """Constrói grafos uses_of / used_by via regex [Nome] nas expressões."""
    uses_of = defaultdict(list)
    used_by = defaultdict(list)
    obj_by_name = defaultdict(list)

    for o in objetos:
        obj_by_name[o["name"]].append(o)

    RE_BRACKET_REF = re.compile(r"\[([^\]]+)\]")

    for o in objetos:
        if not o["expression"]:
            continue
        chave_o = (o["table"], o["name"])
        refs = set(RE_BRACKET_REF.findall(o["expression"]))

        for ref_name in refs:
            if ref_name in obj_by_name:
                for ref_obj in obj_by_name[ref_name]:
                    chave_ref = (ref_obj["table"], ref_obj["name"])
                    if chave_ref != chave_o:
                        uses_of[chave_o].append(ref_obj)
                        used_by[chave_ref].append(o)

    return uses_of, used_by


# ==================== ETAPA 3: REFERÊNCIAS NO RELATÓRIO ====================

def analisar_relatorio(report_dir: Path):
    """Varre JSONs do relatório e mapeia referências (tabela, nome) -> locais."""
    referencias_visuais = defaultdict(list)
    paginas_por_objeto = defaultdict(set)

    def registrar(entity, prop, local_desc, pagina_nome):
        chave = (entity, prop)
        if local_desc not in referencias_visuais[chave]:
            referencias_visuais[chave].append(local_desc)
        if pagina_nome:
            paginas_por_objeto[chave].add(pagina_nome)

    def extrair_refs(obj, local_desc, pagina_nome):
        if isinstance(obj, dict):
            for chave in ("Column", "Measure", "HierarchyLevel"):
                if chave in obj and isinstance(obj[chave], dict):
                    bloco = obj[chave]
                    prop = bloco.get("Property")
                    expr = bloco.get("Expression", {})
                    source_ref = expr.get("SourceRef", {}) if isinstance(expr, dict) else {}
                    entity = source_ref.get("Entity")
                    if entity and prop:
                        registrar(entity, prop, local_desc, pagina_nome)
            for v in obj.values():
                extrair_refs(v, local_desc, pagina_nome)
        elif isinstance(obj, list):
            for item in obj:
                extrair_refs(item, local_desc, pagina_nome)

    def ler_json(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            print(f"  [AVISO] Não consegui ler {path}: {e}")
            return None

    pages_dir = report_dir / "definition" / "pages"

    if pages_dir.is_dir():
        for page_folder in sorted(os.listdir(pages_dir)):
            page_path = pages_dir / page_folder
            if not page_path.is_dir():
                continue

            page_json_path = page_path / "page.json"
            page_display_name = page_folder
            page_data = ler_json(str(page_json_path))

            if page_data and "displayName" in page_data:
                page_display_name = page_data["displayName"]

            if page_data:
                extrair_refs(page_data, f"Página '{page_display_name}' > Filtro de página", page_display_name)

            visuals_dir = page_path / "visuals"
            if visuals_dir.is_dir():
                for visual_folder in sorted(os.listdir(visuals_dir)):
                    visual_json_path = visuals_dir / visual_folder / "visual.json"
                    if not visual_json_path.is_file():
                        continue
                    visual_data = ler_json(str(visual_json_path))
                    if not visual_data:
                        continue
                    visual_type = "desconhecido"
                    try:
                        visual_type = visual_data.get("visual", {}).get("visualType", "desconhecido")
                    except Exception:
                        pass
                    local_desc = f"Página '{page_display_name}' > Visual '{visual_type}' (id {visual_folder})"
                    extrair_refs(visual_data, local_desc, page_display_name)

    report_filters_path = report_dir / "definition" / "filters.json"
    if report_filters_path.is_file():
        report_filters_data = ler_json(str(report_filters_path))
        if report_filters_data:
            extrair_refs(report_filters_data, "Relatório > Filtro global", None)

    return referencias_visuais, paginas_por_objeto


# ==================== ETAPA 4: CLASSIFICAÇÃO E PROPAGAÇÃO ====================

def classificar_objetos(objetos, referencias_visuais, uses_of, used_by):
    """Propaga uso efetivo (BFS) e classifica cada objeto."""
    uso_efetivo = set()

    for o in objetos:
        chave = (o["table"], o["name"])
        if chave in referencias_visuais:
            uso_efetivo.add(chave)

    fila = list(uso_efetivo)
    while fila:
        atual = fila.pop()
        for referenciado in uses_of.get(atual, []):
            chave_ref = (referenciado["table"], referenciado["name"])
            if chave_ref not in uso_efetivo:
                uso_efetivo.add(chave_ref)
                fila.append(chave_ref)

    status_final = {}
    for o in objetos:
        chave = (o["table"], o["name"])
        usado_visual = chave in referencias_visuais
        usado_modelo = len(used_by.get(chave, [])) > 0
        efetivo = chave in uso_efetivo

        if efetivo:
            sf = "Utilizada"
        elif usado_visual or usado_modelo:
            sf = "Cadeia sem uso real (verificar)"
        else:
            sf = "Não utilizada"

        status_final[chave] = sf

    return status_final, uso_efetivo


# ==================== ETAPA 5: PROTEÇÕES ====================

def aplicar_protecoes(para_remover: Set[Tuple[str, str, str]]):
    """Remove do conjunto objetos protegidos. Retorna (filtrado, protegidos)."""
    protegidos = []
    filtrado = set()

    # Componentes de Higienização (sempre preservados)
    TABELAS_HIGIENIZACAO = {"_Hig_CatalogoStatus", "_Hig_Levantamento", "_Aud_CatalogoStatus", "_Aud_Levantamento"}
    MEDIDAS_HIGIENIZACAO_NOMES = {
        "% Não Utilizada na Tabela",
        "% Status na Tabela",
        "Objetos Sem Classificação",
        "Qtd Não Utilizada",
        "Tabela 100% Não Utilizada",
        "Total Objetos da Tabela",
    }

    for tabela, nome, tipo in para_remover:
        protegido = False
        motivo = ""

        if tabela == "stgFuncionarios" and nome in STG_COLUNAS_OBRIGATORIAS:
            protegido = True
            motivo = "Referenciada na partição M do stgFuncionarios"

        if is_data_table(tabela) and nome in COLUNAS_DATA_OBRIGATORIAS:
            protegido = True
            motivo = "Coluna obrigatória em tabela de data"

        # Proteger LocalDateTable_* que são referenciadas por variation blocks
        # (stgFuncionarios.Data de Nascimento/Contratacao/Demissao)
        if tabela.startswith("LocalDateTable_") or tabela.startswith("DateTableTemplate_"):
            protegido = True
            motivo = "Tabela de data referenciada por variation blocks"

        if tabela in TABELAS_HIGIENIZACAO:
            protegido = True
            motivo = "Componente de Higienização (sempre preservado)"

        if tabela == "_Medidas RH" and nome in MEDIDAS_HIGIENIZACAO_NOMES:
            protegido = True
            motivo = "Medida de Higienização (sempre preservada)"

        if protegido:
            protegidos.append({"table": tabela, "name": nome, "tipo": tipo, "motivo": motivo})
        else:
            filtrado.add((tabela, nome, tipo))

    return filtrado, protegidos


# ==================== ETAPA 6: HIGIENIZAÇÃO ====================

def higienizar_tmdl(tables_dir_hig: Path, para_remover: Set):
    """Remove objetos marcados dos .tmdl. Retorna (tabelas_removidas, objetos_removidos).
    
    Se TODOS os objetos (colunas + medidas) de uma tabela estão em para_remover,
    a tabela inteira é removida (arquivo .tmdl deletado).
    """
    tabelas_removidas = []
    objetos_removidos = []

    for tmdl_path in sorted(tables_dir_hig.glob("*.tmdl")):
        table_name = tmdl_path.stem
        tmdl_text = read_text_file(str(tmdl_path))

        # Contar todos os objetos da tabela
        all_columns = find_object_blocks(tmdl_text, "column")
        all_measures = find_object_blocks(tmdl_text, "measure")
        total_objetos = len(all_columns) + len(all_measures)

        # Contar quantos estão marcados para remoção
        marcados = 0
        blocos_para_remover = []

        for block in all_columns:
            if (table_name, block["name"], "Coluna") in para_remover or \
               (table_name, block["name"], "Coluna Calculada") in para_remover:
                marcados += 1
                blocos_para_remover.append(block)
                tipo = "Coluna" if (table_name, block["name"], "Coluna") in para_remover else "Coluna Calculada"
                objetos_removidos.append({"table": table_name, "name": block["name"], "tipo": tipo})

        for block in all_measures:
            if (table_name, block["name"], "Medida") in para_remover:
                marcados += 1
                blocos_para_remover.append(block)
                objetos_removidos.append({"table": table_name, "name": block["name"], "tipo": "Medida"})

        if not blocos_para_remover:
            continue

        # Se TODOS os objetos da tabela estão marcados, remover tabela inteira
        if total_objetos > 0 and marcados == total_objetos:
            tmdl_path.unlink()
            tabelas_removidas.append(table_name)
            print(f"  [REMOVIDA TABELA] {table_name} (todos os {total_objetos} objetos não utilizados)")
        else:
            tmdl_limpo = remove_blocks_from_text(tmdl_text, blocos_para_remover)
            # Verificar se ficou vazia após remoção parcial
            if is_table_empty(tmdl_limpo):
                tmdl_path.unlink()
                tabelas_removidas.append(table_name)
                print(f"  [REMOVIDA TABELA] {table_name} (ficou vazia após remoções)")
            else:
                with open(tmdl_path, "w", encoding="utf-8", newline="\n") as f:
                    f.write(tmdl_limpo)
                print(f"  [LIMPA] {table_name}: {len(blocos_para_remover)}/{total_objetos} objetos removidos")

    return tabelas_removidas, objetos_removidos


def higienizar_relationships(rel_path: Path, tabelas_removidas: List[str], objetos_removidos: List[Dict]):
    """Remove relacionamentos que referenciam tabelas/colunas removidas."""
    rel_text = read_text_file(str(rel_path))
    lines = rel_text.split("\n")

    tabelas_removidas_set = set(tabelas_removidas)
    colunas_removidas_set = set()
    for o in objetos_removidos:
        colunas_removidas_set.add((o["table"], o["name"]))

    rel_blocks = []
    i = 0
    while i < len(lines):
        m = re.match(r"^relationship\s+(\S+)", lines[i])
        if m:
            rel_id = m.group(1)
            start = i
            j = i + 1
            while j < len(lines):
                if lines[j].strip() == "" or re.match(r"^relationship\s+", lines[j]):
                    break
                j += 1
            end = j
            block_text = "\n".join(lines[start:end])

            from_m = re.search(r"fromColumn:\s*(.+)", block_text)
            to_m = re.search(r"toColumn:\s*(.+)", block_text)
            from_col = from_m.group(1).strip() if from_m else ""
            to_col = to_m.group(1).strip() if to_m else ""

            from_table, from_colname = parse_table_col(from_col)
            to_table, to_colname = parse_table_col(to_col)

            remover = False
            motivo = ""

            if from_table in tabelas_removidas_set:
                remover = True
                motivo = f"Tabela '{from_table}' removida"
            elif to_table in tabelas_removidas_set:
                remover = True
                motivo = f"Tabela '{to_table}' removida"
            elif (from_table, from_colname) in colunas_removidas_set:
                remover = True
                motivo = f"Coluna '{from_table}.{from_colname}' removida"
            elif (to_table, to_colname) in colunas_removidas_set:
                remover = True
                motivo = f"Coluna '{to_table}.{to_colname}' removida"

            rel_blocks.append({
                "id": rel_id,
                "start": start,
                "end": end,
                "from_col": from_col,
                "to_col": to_col,
                "remover": remover,
                "motivo": motivo,
            })
            i = j
        else:
            i += 1

    rels_removidos = [r for r in rel_blocks if r["remover"]]
    rels_manter = [r for r in rel_blocks if not r["remover"]]

    for r in sorted(rels_removidos, key=lambda x: x["start"], reverse=True):
        del lines[r["start"]:r["end"]]

    with open(rel_path, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))

    return rels_removidos, rels_manter


def higienizar_model(model_path: Path, tabelas_removidas: List[str]):
    """Remove linhas 'ref table X' de tabelas removidas em model.tmdl."""
    model_text = read_text_file(str(model_path))
    model_lines = model_text.split("\n")
    new_lines = []
    refs_removidas = []

    tabelas_removidas_set = set(tabelas_removidas)

    for line in model_lines:
        m = re.match(r"^ref\s+table\s+(?:'([^']+)'|(\S+))", line.strip())
        if m:
            table_name = m.group(1) or m.group(2)
            if table_name in tabelas_removidas_set:
                refs_removidas.append(table_name)
                continue
        new_lines.append(line)

    with open(model_path, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(new_lines))

    return refs_removidas


# ==================== ETAPA 6.5: COMPONENTES DE HIGIENIZAÇÃO ====================

def gerar_csv_levantamento(csv_path: Path, objetos: List[Dict], status_final: Dict,
                          referencias_visuais: Dict, used_by: Dict, paginas_por_objeto: Dict,
                          para_remover: set = None, modo_auditoria: bool = False):
    """Gera o CSV de levantamento a partir dos dados em memória."""
    import csv as csv_module

    if para_remover is None:
        para_remover = set()

    linhas = []
    for o in objetos:
        chave = (o["table"], o["name"])
        usado_visual = chave in referencias_visuais
        usado_modelo = len(used_by.get(chave, [])) > 0

        usos_visuais = referencias_visuais.get(chave, [])
        usos_modelo_objs = used_by.get(chave, [])
        usos_modelo = [f"{r['tipo']} '{r['name']}' (tabela '{r['table']}')" for r in usos_modelo_objs]

        efetivo = status_final.get(chave) == "Utilizada"
        sf = status_final.get(chave, "Não utilizada")

        if efetivo:
            status = "Utilizada"
        elif usado_visual or usado_modelo:
            status = "Utilizada"
        else:
            status = "Não utilizada"

        paginas = sorted(paginas_por_objeto.get(chave, set()))

        # Status pós-higienização
        chave_remover = (o["table"], o["name"], o["tipo"])
        if chave_remover in para_remover:
            status_pos = "Removido"
        else:
            status_pos = "Mantido"

        # Se é protegido mas não utilizado, mudar StatusFinal para clareza
        # APENAS no modo completo (não auditoria)
        if sf == "Não utilizada" and status_pos == "Mantido" and not modo_auditoria:
            sf = "Protegida (M query)"

        linhas.append({
            "Tipo": o["tipo"],
            "Tabela": o["table"],
            "Nome": o["name"],
            "UtilizadaEmVisual": "Sim" if usado_visual else "Não",
            "UtilizadaNoModelo": "Sim" if usado_modelo else "Não",
            "Status": status,
            "QtdLocaisDeUso": len(usos_visuais) + len(usos_modelo),
            "LocaisDeUsoVisual": " | ".join(usos_visuais),
            "LocaisDeUsoModelo": " | ".join(usos_modelo),
            "PaginasDeUso": " | ".join(paginas),
            "UsoEfetivo": "Sim" if efetivo else "Não",
            "StatusFinal": sf,
            "StatusPosHigienizacao": status_pos,
        })

    campos = [
        "Tipo", "Tabela", "Nome",
        "UtilizadaEmVisual", "UtilizadaNoModelo", "Status",
        "QtdLocaisDeUso", "LocaisDeUsoVisual", "LocaisDeUsoModelo", "PaginasDeUso",
        "UsoEfetivo", "StatusFinal", "StatusPosHigienizacao"
    ]

    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = csv_module.DictWriter(f, fieldnames=campos, delimiter=";")
        writer.writeheader()
        writer.writerows(linhas)

    return len(linhas)


def gerar_uuid():
    """Gera um UUID único para lineageTag."""
    import uuid
    return str(uuid.uuid4())


def substituir_lineage_tags(template: str) -> str:
    """Substitui todos os lineageTags (PLACEHOLDER ou fixos) por UUIDs únicos."""
    import re
    def replace_tag(match):
        return f"lineageTag: {gerar_uuid()}"
    # Substituir tanto PLACEHOLDER quanto UUIDs fixos
    return re.sub(r"lineageTag: (PLACEHOLDER|[0-9a-f-]+)", replace_tag, template)


