def criar_tmdl_catalogo() -> str:
    """Cria o conteúdo do .tmdl para a tabela _Hig_CatalogoStatus (DAX calculada)."""
    template = '''table '_Hig_CatalogoStatus'
	lineageTag: PLACEHOLDER

	column Tipo
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [Tipo]

		annotation SummarizationSetBy = Automatic

	column Tabela
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [Tabela]

		annotation SummarizationSetBy = Automatic

	column Nome
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [Nome]

		annotation SummarizationSetBy = Automatic

	column StatusFinal
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [StatusFinal]

		annotation SummarizationSetBy = Automatic

	column LocaisDeUsoVisual
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [LocaisDeUsoVisual]

		annotation SummarizationSetBy = Automatic

	column LocaisDeUsoModelo
		lineageTag: PLACEHOLDER
		summarizeBy: none
		isNameInferred
		sourceColumn: [LocaisDeUsoModelo]

		annotation SummarizationSetBy = Automatic

	partition '_Hig_CatalogoStatus' = calculated
		mode: import
		source = ```
			
			VAR Colunas =
			    SELECTCOLUMNS(
			        FILTER (
			            INFO.VIEW.COLUMNS(),
			            [IsHidden] = FALSE
			        ),
			        "Tipo", IF ( [Type] = "2", "Coluna Calculada", "Coluna" ),
			        "Tabela", [Table],
			        "Nome", [Name]
			    )
			
			VAR Medidas =
			    SELECTCOLUMNS(
			        INFO.VIEW.MEASURES(),
			        "Tipo", "Medida",
			        "Tabela", [Table],
			        "Nome", [Name]
			    )
			VAR CatalogoModelo = UNION ( Colunas, Medidas )
			RETURN
			    ADDCOLUMNS (
			        CatalogoModelo,
			        "StatusFinal",
			        LOOKUPVALUE (
			            '_Hig_Levantamento'[StatusFinal],
			            '_Hig_Levantamento'[Tabela], [Tabela],
			            '_Hig_Levantamento'[Nome], [Nome]
			        ),
			        "LocaisDeUsoVisual",
			        LOOKUPVALUE (
			            '_Hig_Levantamento'[LocaisDeUsoVisual],
			            '_Hig_Levantamento'[Tabela], [Tabela],
			            '_Hig_Levantamento'[Nome], [Nome]
			        ),
			        "LocaisDeUsoModelo",
			        LOOKUPVALUE (
			            '_Hig_Levantamento'[LocaisDeUsoModelo],
			            '_Hig_Levantamento'[Tabela], [Tabela],
			            '_Hig_Levantamento'[Nome], [Nome]
			        )
			    )
			
			```

	annotation PBI_Id = 1cedf08e2e24438e8a102e7eb572907e
'''
    return substituir_lineage_tags(template)
    return substituir_lineage_tags(template)


