def gerar_csv_protecoes(csv_path: Path, protegidos: list = None):
    """Gera CSV com os itens protegidos reais."""
    import csv as csv_module
    
    if protegidos is None:
        protegidos = []
    
    linhas = []
    for p in protegidos:
        linhas.append({
            "Nome": p.get("name", ""),
            "Tabela": p.get("table", ""),
            "Tipo": p.get("tipo", ""),
            "Status": "Protegida (M query)",
            "Motivo": p.get("motivo", ""),
        })
    
    campos = ["Nome", "Tabela", "Tipo", "Status", "Motivo"]
    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = csv_module.DictWriter(f, fieldnames=campos, delimiter=";")
        writer.writeheader()
        writer.writerows(linhas)
    return len(linhas)


def gerar_csv_removidos(csv_path: Path, objetos_removidos: List[Dict], objetos: List[Dict], referencias_visuais: Dict, used_by: Dict, paginas_por_objeto: Dict):
    """Gera CSV com detalhes dos objetos removidos."""
    import csv as csv_module

    # Indexar objetos originais para buscar locais de uso
    obj_index = {}
    for o in objetos:
        chave = (o["table"], o["name"])
        obj_index[chave] = o

    linhas = []
    for rem in objetos_removidos:
        chave = (rem["table"], rem["name"])
        usos_visuais = referencias_visuais.get(chave, [])
        usos_modelo_objs = used_by.get(chave, [])
        usos_modelo = [f"{r['tipo']} '{r['name']}' (tabela '{r['table']}')" for r in usos_modelo_objs]
        paginas = sorted(paginas_por_objeto.get(chave, set()))

        linhas.append({
            "Tipo": rem["tipo"],
            "Tabela": rem["table"],
            "Nome": rem["name"],
            "MotivoRemocao": "Não utilizada",
            "LocaisDeUsoVisual": " | ".join(usos_visuais),
            "LocaisDeUsoModelo": " | ".join(usos_modelo),
            "PaginasDeUso": " | ".join(paginas),
        })

    campos = ["Tipo", "Tabela", "Nome", "MotivoRemocao", "LocaisDeUsoVisual", "LocaisDeUsoModelo", "PaginasDeUso"]

    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = csv_module.DictWriter(f, fieldnames=campos, delimiter=";")
        writer.writeheader()
        writer.writerows(linhas)

    return len(linhas)


def gerar_csv_resumo(csv_path: Path, objetos: List[Dict], objetos_removidos: List[Dict], tabelas_removidas: List[str]):
    """Gera CSV com resumo antes/depois por tabela."""
    import csv as csv_module

    # Contar objetos antes por tabela
    antes = {}
    for o in objetos:
        t = o["table"]
        antes[t] = antes.get(t, 0) + 1

    # Contar removidos por tabela
    removidos = {}
    for r in objetos_removidos:
        t = r["table"]
        removidos[t] = removidos.get(t, 0) + 1

    # Calcular depois e percentual
    linhas = []
    for t in sorted(set(list(antes.keys()) + list(removidos.keys()))):
        qtd_antes = antes.get(t, 0)
        qtd_removidos = removidos.get(t, 0)
        qtd_depois = qtd_antes - qtd_removidos

        # Se a tabela foi completamente removida
        if t in tabelas_removidas:
            qtd_depois = 0

        linhas.append({
            "Tabela": t,
            "ObjetosAntes": qtd_antes,
            "ObjetosDepois": qtd_depois,
            "Removidos": qtd_removidos,
        })

    campos = ["Tabela", "ObjetosAntes", "ObjetosDepois", "Removidos"]

    with open(csv_path, "w", newline="", encoding="utf-8-sig") as f:
        writer = csv_module.DictWriter(f, fieldnames=campos, delimiter=";")
        writer.writeheader()
        writer.writerows(linhas)

    return len(linhas)


def criar_tabela_medidas(modo_auditoria: bool = False) -> str:
    """Cria o TMDL para a tabela _Hig_Medidas com as medidas de higienização."""
    # Medida % Removido apenas no modo completo (não auditoria)
    medida_removido = '''	measure '% Removido' =
			DIVIDE ( SUM ( _Hig_Resumo[Removidos] ), SUM ( _Hig_Resumo[ObjetosAntes] ) )
		formatString: 0.00%
		lineageTag: PLACEHOLDER

''' if not modo_auditoria else ''

    template = '''table _Hig_Medidas
	lineageTag: PLACEHOLDER

''' + medida_removido + '''	measure '% Não Utilizada na Tabela' =
			DIVIDE ( [Qtd Não Utilizada], [Total Objetos da Tabela] )
		formatString: 0.00%
		lineageTag: PLACEHOLDER

	measure '% Status na Tabela' =
			DIVIDE ( COUNTROWS ( '_Hig_CatalogoStatus' ), [Total Objetos da Tabela] )
		formatString: 0.00%
		lineageTag: PLACEHOLDER

	measure 'Objetos Sem Classificação' =
			CALCULATE (
			    COUNTROWS ( '_Hig_CatalogoStatus' ),
			    ISBLANK ( '_Hig_CatalogoStatus'[StatusFinal] )
			)
		formatString: 0
		lineageTag: PLACEHOLDER

	measure 'Qtd Não Utilizada' =
			CALCULATE (
			    COUNTROWS ( '_Hig_CatalogoStatus' ),
			    '_Hig_CatalogoStatus'[StatusFinal] = "Não utilizada"
			)
		formatString: 0
		lineageTag: PLACEHOLDER

	measure 'Tabela 100% Não Utilizada' =
			IF ( [% Não Utilizada na Tabela] = 1, "Sim", "Não" )
		lineageTag: PLACEHOLDER

	measure 'Total Objetos da Tabela' =
			CALCULATE (
			    COUNTROWS ( '_Hig_CatalogoStatus' ),
			    ALLEXCEPT ( '_Hig_CatalogoStatus', '_Hig_CatalogoStatus'[Tabela] )
			)
		formatString: 0
		lineageTag: PLACEHOLDER

	partition _Hig_Medidas = calculated
		mode: import
		source = DATATABLE("Dummy", INTEGER, {{1}})

	annotation PBI_ResultType = Table
'''
    return substituir_lineage_tags(template)


