def extrair_template_auditoria(dest_dir: Path):
    """Extrai o template embutido da pagina Higienizacao (modo auditoria)."""
    import base64
    dest_dir.mkdir(parents=True, exist_ok=True)
    for rel_path, b64_content in TEMPLATE_PAGINA_AUDITORIA.items():
        out_path = dest_dir / rel_path
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_bytes(base64.b64decode(b64_content))
    return dest_dir


def extrair_template_pagina(dest_dir: Path):
    """Extrai o template embutido da pagina Higienizacao."""
    import base64
    dest_dir.mkdir(parents=True, exist_ok=True)
    for rel_path, b64_content in TEMPLATE_PAGINA_HIGIENIZACAO.items():
        out_path = dest_dir / rel_path
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_bytes(base64.b64decode(b64_content))
    return dest_dir

def copiar_pagina_higienizacao(report_dir_orig: Path, report_dir_hig: Path, modo_auditoria: bool = False):
    """
    Cria a página 'Higienização' no relatório higienizado usando o template embutido.
    No modo auditoria, usa template com 16 visuais e altura 1850.
    No modo completo, usa template com 20 visuais e altura 3000.
    """
    # ID padrão da página Higienização (mantido do projeto de referência)
    PAGINA_ID = "8696bfc15cbead1e1080"

    pages_hig = report_dir_hig / "definition" / "pages"
    page_hig_dir = pages_hig / PAGINA_ID

    # Verificar se já existe no higienizado (para não recriar)
    if page_hig_dir.exists():
        shutil.rmtree(page_hig_dir)

    # Usar template apropriado para o modo
    if modo_auditoria:
        extrair_template_auditoria(page_hig_dir)
        qtd_visuais = len(list((page_hig_dir / "visuals").rglob("visual.json"))) if (page_hig_dir / "visuals").exists() else 0
        print(f"    Página 'Auditoria' criada do template auditoria ({qtd_visuais} visuais, altura 1850)")
    else:
        extrair_template_pagina(page_hig_dir)
        qtd_visuais = len(list((page_hig_dir / "visuals").rglob("visual.json"))) if (page_hig_dir / "visuals").exists() else 0
        print(f"    Página 'Higienização' criada do template embutido ({qtd_visuais} visuais)")

    # Adicionar filtro para mostrar apenas objetos "Mantido" (pós-higienização)
    page_json_path = page_hig_dir / "page.json"
    if page_json_path.exists():
        with open(page_json_path, "r", encoding="utf-8") as f:
            page_data = json.load(f)

        if "filterConfig" not in page_data:
            page_data["filterConfig"] = {"filters": []}

        # No modo auditoria, NÃO aplicar filtro StatusPosHigienizacao
        # para mostrar TODOS os itens (incluindo os que seriam removidos)
        if not modo_auditoria:
            filtro_existe = any(
                f.get("field", {}).get("Column", {}).get("Property") == "StatusPosHigienizacao"
                for f in page_data["filterConfig"].get("filters", [])
            )

            if not filtro_existe:
                filtro_mantido = {
                    "name": "filtro_pos_higienizacao",
                    "field": {
                        "Column": {
                            "Expression": {"SourceRef": {"Entity": "_Hig_Levantamento"}},
                            "Property": "StatusPosHigienizacao"
                        }
                    },
                    "type": "Categorical",
                    "filter": {
                        "Version": 2,
                        "From": [{"Name": "_", "Entity": "_Hig_Levantamento", "Type": 0}],
                        "Where": [{
                            "Condition": {
                                "In": {
                                    "Expressions": [{
                                        "Column": {
                                            "Expression": {"SourceRef": {"Source": "_"}},
                                            "Property": "StatusPosHigienizacao"
                                        }
                                    }],
                                    "Values": [[{"Literal": {"Value": "'Mantido'"}}]]
                                }
                            }
                        }]
                    },
                    "howCreated": "User"
                }
                page_data["filterConfig"]["filters"].append(filtro_mantido)
                print(f"    Filtro 'StatusPosHigienizacao = Mantido' adicionado à página")

            # Adicionar filtro _Hig_Protecoes.Tabela (apenas modo higienização)
            filtro_protecoes_existe = any(
                f.get("field", {}).get("Column", {}).get("Expression", {}).get("SourceRef", {}).get("Entity") == "_Hig_Protecoes"
                for f in page_data["filterConfig"].get("filters", [])
            )
            if not filtro_protecoes_existe:
                filtro_protecoes = {
                    "name": "filtro_protecoes_tabela",
                    "field": {
                        "Column": {
                            "Expression": {"SourceRef": {"Entity": "_Hig_Protecoes"}},
                            "Property": "Tabela"
                        }
                    },
                    "type": "Categorical",
                    "filter": {
                        "Version": 2,
                        "From": [{"Name": "_", "Entity": "_Hig_Protecoes", "Type": 0}],
                        "Where": []
                    },
                    "howCreated": "User"
                }
                page_data["filterConfig"]["filters"].append(filtro_protecoes)
                print(f"    Filtro '_Hig_Protecoes.Tabela' adicionado à página")
        else:
            print("    [MODO AUDITORIA] Filtro StatusPosHigienizacao não aplicado")
            # Remover filtro StatusPosHigienizacao se existir no template
            page_data["filterConfig"]["filters"] = [
                f for f in page_data["filterConfig"].get("filters", [])
                if f.get("field", {}).get("Column", {}).get("Property") != "StatusPosHigienizacao"
            ]

        # Salvar page.json
        with open(page_json_path, "w", encoding="utf-8") as f:
            json.dump(page_data, f, indent=2, ensure_ascii=False)

    # Atualizar pages.json para incluir a página
    pages_json_path = pages_hig / "pages.json"
    if pages_json_path.exists():
        with open(pages_json_path, "r", encoding="utf-8") as f:
            pages_data = json.load(f)

        if "pageOrder" not in pages_data:
            pages_data["pageOrder"] = []

        if PAGINA_ID not in pages_data["pageOrder"]:
            pages_data["pageOrder"].append(PAGINA_ID)

        with open(pages_json_path, "w", encoding="utf-8") as f:
            json.dump(pages_data, f, indent=2, ensure_ascii=False)
        print(f"    Página registrada em pages.json")

    return True


def aplicar_identidade_auditoria(semantic_model_dir_hig: Path, report_dir_hig: Path):
    """
    Modo auditoria: renomeia as tabelas _Hig_* para _Aud_* (arquivos, DAX/M, model,
    relationships e visuais da pagina) e ajusta nome da pagina e titulo do textbox.
    """
    nomes = ("Levantamento", "CatalogoStatus", "Medidas", "ObjetosRemovidos", "Resumo", "Protecoes")
    padrao = re.compile(rb"_Hig_(" + b"|".join(n.encode() for n in nomes) + rb")")

    def trocar(dados: bytes) -> bytes:
        dados = padrao.sub(rb"_Aud_\1", dados)
        return dados.replace(b"rel_higienizacao_catalogo", b"rel_auditoria_catalogo")

    definition = semantic_model_dir_hig / "definition"
    tables_dir = definition / "tables"

    # 1. Arquivos de tabela
    if tables_dir.exists():
        for arq in sorted(tables_dir.glob("_Hig_*.tmdl")):
            if arq.stem[len("_Hig_"):] not in nomes:
                continue
            novo = tables_dir / arq.name.replace("_Hig_", "_Aud_", 1)
            novo.write_bytes(trocar(arq.read_bytes()))
            arq.unlink()
            print(f"    [AUDITORIA] Tabela {arq.stem} -> {novo.stem}")

    # 2. model.tmdl e relationships.tmdl
    for nome_arq in ("model.tmdl", "relationships.tmdl"):
        p = definition / nome_arq
        if p.exists():
            p.write_bytes(trocar(p.read_bytes()))

    # 3. Pagina do relatorio
    pagina_dir = report_dir_hig / "definition" / "pages" / "8696bfc15cbead1e1080"
    if not pagina_dir.exists():
        print("    [AUDITORIA] Aviso: pasta da pagina nao encontrada")
        return

    titulos = (
        ("Higieniza\u00e7\u00e3o de Dados do BI".encode("utf-8"), "Auditoria de Dados do BI".encode("utf-8")),
        (b"Higieniza\\u00e7\\u00e3o de Dados do BI", b"Auditoria de Dados do BI"),
    )
    n_titulo = 0
    for arq in pagina_dir.rglob("*.json"):
        dados = trocar(arq.read_bytes())
        for antigo, novo_txt in titulos:
            n_titulo += dados.count(antigo)
            dados = dados.replace(antigo, novo_txt)
        arq.write_bytes(dados)

    page_json = pagina_dir / "page.json"
    if page_json.exists():
        with open(page_json, "r", encoding="utf-8") as f:
            page_data = json.load(f)
        page_data["displayName"] = "Auditoria"
        with open(page_json, "w", encoding="utf-8") as f:
            json.dump(page_data, f, indent=2, ensure_ascii=False)

    print(f"    [AUDITORIA] Pagina renomeada para 'Auditoria' ({n_titulo} titulo(s) de textbox ajustado(s))")

    # 4. Textos "Higieniza..." que ainda restam na pagina (para conferencia)
    restos = set()
    for arq in pagina_dir.rglob("*.json"):
        texto = arq.read_text(encoding="utf-8-sig", errors="replace")
        for m in re.finditer(r'"[^"\n]*[Hh]igieniza[^"\n]*"', texto):
            t = m.group(0)
            if "StatusPosHigienizacao" in t or "filtro_pos_higienizacao" in t:
                continue
            restos.add(t[:100])
    for t in sorted(restos):
        print(f"    [AUDITORIA] Texto ainda com 'Higienizacao' na pagina: {t}")


def injetar_componentes_higienizacao(
    semantic_model_dir_hig: Path,
    report_dir_orig: Path,
    report_dir_hig: Path,
    csv_path: Path,
    project_name: str,
    objetos: List[Dict],
    status_final: Dict,
    referencias_visuais: Dict,
    used_by: Dict,
    paginas_por_objeto: Dict,
    objetos_removidos: List[Dict],
    tabelas_removidas: List[str],
    para_remover: set,
    protegidos: list,
    modo_auditoria: bool = False,
    no_cache: bool = False,
):
    """Cria os componentes de Higienização no modelo higienizado."""
    tables_dir = semantic_model_dir_hig / "definition" / "tables"

    # 1. Gerar CSV
    print("  Gerando CSV de levantamento...")
    qtd_csv = gerar_csv_levantamento(
        csv_path, objetos, status_final,
        referencias_visuais, used_by, paginas_por_objeto,
        para_remover, modo_auditoria
    )
    print(f"    CSV gerado: {qtd_csv} objetos em {csv_path.name}")

    # 2. Criar tabela _Hig_Levantamento (import CSV)
    csv_path_str = str(csv_path)  # Manter formato nativo do Windows (backslashes)
    tmdl_levantamento = criar_tmdl_levantamento(csv_path_str)
    (tables_dir / "_Hig_Levantamento.tmdl").write_text(
        tmdl_levantamento, encoding="utf-8", newline="\n"
    )
    print("    Tabela _Hig_Levantamento criada")

    # 3. Criar tabela _Hig_CatalogoStatus (DAX calculada)
    tmdl_catalogo = criar_tmdl_catalogo()
    (tables_dir / "_Hig_CatalogoStatus.tmdl").write_text(
        tmdl_catalogo, encoding="utf-8", newline="\n"
    )
    print("    Tabela _Hig_CatalogoStatus criada")

    # 4. Criar tabela _Hig_Medidas com todas as medidas de higienização
    print("  Criando tabela _Hig_Medidas...")
    tmdl_medidas = criar_tabela_medidas(modo_auditoria)
    (tables_dir / "_Hig_Medidas.tmdl").write_text(
        tmdl_medidas, encoding="utf-8", newline="\n"
    )
    print("    Tabela _Hig_Medidas criada (7 medidas)")

    # 5. Atualizar model.tmdl com novas tabelas
    model_path = semantic_model_dir_hig / "definition" / "model.tmdl"
    model_text = read_text_file(str(model_path))

    # Adicionar ref table se não existir
    novas_tabelas = ["_Hig_Levantamento", "'_Hig_CatalogoStatus'"]
    for tabela in novas_tabelas:
        ref_line = f"ref table {tabela}"
        if ref_line not in model_text:
            # Adicionar antes de 'ref cultureInfo'
            if "ref cultureInfo" in model_text:
                model_text = model_text.replace(
                    "ref cultureInfo",
                    f"{ref_line}\n\nref cultureInfo"
                )
            else:
                model_text = model_text.rstrip() + f"\n{ref_line}\n"

    model_path.write_text(model_text, encoding="utf-8", newline="\n")
    print("    model.tmdl atualizado")

    # 6. Adicionar relacionamento entre _Catálogo e _levantamento (muitos-para-muitos)
    rel_path = semantic_model_dir_hig / "definition" / "relationships.tmdl"
    rel_text = read_text_file(str(rel_path))

    rel_id = "rel_higienizacao_catalogo"
    if rel_id not in rel_text:
        novo_rel = f'''
relationship {rel_id}
	fromCardinality: many
	toCardinality: many
	fromColumn: _Hig_Levantamento.Tabela
	toColumn: '_Hig_CatalogoStatus'.Tabela
'''
        rel_text = rel_text.rstrip() + "\n" + novo_rel + "\n"
        rel_path.write_text(rel_text, encoding="utf-8", newline="\n")
        print("    Relacionamento _levantamento -> _Catálogo (muitos-para-muitos) adicionado")

    # 6.1 Criar tabela _Hig_ObjetosRemovidos (detalhes do que foi removido)
    # No modo auditoria, não criar tabelas de dados pós-limpeza
    if not modo_auditoria:
        print("  Criando tabela _Hig_ObjetosRemovidos...")
        csv_removidos_path = semantic_model_dir_hig / f"removidos_{project_name}.csv"
        qtd_removidos = gerar_csv_removidos(
            csv_removidos_path, objetos_removidos, objetos,
            referencias_visuais, used_by, paginas_por_objeto
        )
        csv_removidos_str = str(csv_removidos_path)
        tmdl_removidos = criar_tabela_removidos(csv_removidos_str)
        (tables_dir / "_Hig_ObjetosRemovidos.tmdl").write_text(
            tmdl_removidos, encoding="utf-8", newline="\n"
        )
        print(f"    Tabela _Hig_ObjetosRemovidos criada ({qtd_removidos} objetos)")

        # 6.2 Criar tabela _Hig_Resumo (dados para gráfico comparativo)
        print("  Criando tabela _Hig_Resumo...")
        csv_resumo_path = semantic_model_dir_hig / f"resumo_{project_name}.csv"
        qtd_resumo = gerar_csv_resumo(
            csv_resumo_path, objetos, objetos_removidos, tabelas_removidas
        )
        csv_resumo_str = str(csv_resumo_path)
        tmdl_resumo = criar_tabela_resumo(csv_resumo_str)
        (tables_dir / "_Hig_Resumo.tmdl").write_text(
            tmdl_resumo, encoding="utf-8", newline="\n"
        )
        print(f"    Tabela _Hig_Resumo criada ({qtd_resumo} tabelas)")

        # 6.2.1 Criar tabela _Hig_Protecoes (regras de proteção)
        print("  Criando tabela _Hig_Protecoes...")
        csv_protecoes_path = semantic_model_dir_hig / f"protecoes_{project_name}.csv"
        qtd_protecoes = gerar_csv_protecoes(csv_protecoes_path, protegidos)
        csv_protecoes_str = str(csv_protecoes_path)
        tmdl_protecoes = criar_tabela_protecoes(csv_protecoes_str)
        (tables_dir / "_Hig_Protecoes.tmdl").write_text(
            tmdl_protecoes, encoding="utf-8", newline="\n"
        )
        print(f"    Tabela _Hig_Protecoes criada ({qtd_protecoes} regras)")
    else:
        print("  [MODO AUDITORIA] Tabelas pós-limpeza não serão criadas")

    # 6.3 Atualizar model.tmdl com novas tabelas
    if modo_auditoria:
        novas_tabelas_extra = ["_Hig_Medidas"]
    else:
        novas_tabelas_extra = ["_Hig_ObjetosRemovidos", "_Hig_Resumo", "_Hig_Protecoes", "_Hig_Medidas"]
    for tabela in novas_tabelas_extra:
        ref_line = f"ref table {tabela}"
        if ref_line not in model_text:
            if "ref cultureInfo" in model_text:
                model_text = model_text.replace(
                    "ref cultureInfo",
                    f"{ref_line}\n\nref cultureInfo"
                )
            else:
                model_text = model_text.rstrip() + f"\n{ref_line}\n"
    model_path.write_text(model_text, encoding="utf-8", newline="\n")
    print("    model.tmdl atualizado com novas tabelas")

    # Remover tabelas antigas (se existirem) para evitar duplicatas
    # No modo auditoria, não remover nada
    if not modo_auditoria:
        tabelas_antigas = ["_Catálogo Modelo com Status", "_levantamento_uso_objetos"]
        for tabela_antiga in tabelas_antigas:
            arquivo_antigo = tables_dir / f"{tabela_antiga}.tmdl"
            if arquivo_antigo.exists():
                arquivo_antigo.unlink()
                print(f"    Tabela antiga removida: {tabela_antiga}")

    # 7. Copiar/criar página Higienização no relatório
    print("  Configurando página de Higienização no relatório...")
    copiar_pagina_higienizacao(report_dir_orig, report_dir_hig, modo_auditoria)

    # Remover cache se solicitado (força reload no Power BI)
    if no_cache:
        cache_path = semantic_model_dir_hig / ".pbi" / "cache.abf"
        if cache_path.exists():
            cache_path.unlink()
            print("    Cache .abf removido (--no-cache)")

    # Modo auditoria: tabelas _Hig_* viram _Aud_* e a pagina vira "Auditoria"
    if modo_auditoria:
        aplicar_identidade_auditoria(semantic_model_dir_hig, report_dir_hig)

    print("  Componentes de Higienização criados com sucesso!")


