def gerar_relatorio(
    rel_path: Path,
    project_name: str,
    project_name_hig: str,
    objetos: List[Dict],
    status_final: Dict,
    tabelas_removidas: List[str],
    objetos_removidos: List[Dict],
    rels_removidos: List[Dict],
    protegidos: List[Dict],
):
    """Gera RELATORIO_HIGIENIZACAO.md."""
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    qtd_utilizada = sum(1 for v in status_final.values() if v == "Utilizada")
    qtd_cadeia = sum(1 for v in status_final.values() if v == "Cadeia sem uso real (verificar)")
    qtd_nao_utilizada = sum(1 for v in status_final.values() if v == "Não utilizada")

    removidos_por_tabela = defaultdict(list)
    for o in objetos_removidos:
        removidos_por_tabela[o["table"]].append(o)

    r = []
    r.append(f"# Relatório de Higienização — {project_name_hig}")
    r.append("")
    r.append(f"**Data/Hora:** {now}")
    r.append(f"**Projeto Original:** {project_name}")
    r.append(f"**Critério:** StatusFinal = \"Não utilizada\"")
    r.append("")
    r.append("---")
    r.append("")
    r.append("## Resumo")
    r.append("")
    r.append("| Métrica | Valor |")
    r.append("|---------|-------|")
    r.append(f"| Tabelas removidas | {len(tabelas_removidas)} |")
    r.append(f"| Objetos removidos (total) | {len(objetos_removidos)} |")
    r.append(f"| — Colunas | {sum(1 for o in objetos_removidos if o['tipo'] == 'Coluna')} |")
    r.append(f"| — Colunas Calculadas | {sum(1 for o in objetos_removidos if o['tipo'] == 'Coluna Calculada')} |")
    r.append(f"| — Medidas | {sum(1 for o in objetos_removidos if o['tipo'] == 'Medida')} |")
    r.append(f"| Relacionamentos removidos | {len(rels_removidos)} |")
    r.append(f"| Objetos protegidos (não removidos) | {len(protegidos)} |")
    r.append("")
    r.append("### Estatísticas de Classificação Original")
    r.append("")
    r.append("| Status | Quantidade |")
    r.append("|--------|------------|")
    r.append(f"| Utilizada | {qtd_utilizada} |")
    r.append(f"| Cadeia sem uso real (verificar) | {qtd_cadeia} |")
    r.append(f"| Não utilizada | {qtd_nao_utilizada} |")
    r.append("")
    r.append("---")
    r.append("")
    r.append("## Tabelas Completamente Removidas")
    r.append("")
    if tabelas_removidas:
        r.append("| Tabela | Motivo |")
        r.append("|--------|--------|")
        for t in tabelas_removidas:
            r.append(f"| {t} | Todos os objetos não utilizados |")
    else:
        r.append("_Nenhuma tabela completamente removida._")
    r.append("")
    r.append("---")
    r.append("")
    r.append("## Objetos Removidos por Tabela")
    r.append("")

    for tabela in sorted(removidos_por_tabela.keys()):
        r.append(f"### {tabela}")
        r.append("")
        r.append("| Tipo | Nome |")
        r.append("|------|------|")
        for o in sorted(removidos_por_tabela[tabela], key=lambda x: (x["tipo"], x["name"])):
            r.append(f"| {o['tipo']} | {o['name']} |")
        r.append("")

    r.append("---")
    r.append("")
    r.append("## Relacionamentos Removidos")
    r.append("")
    if rels_removidos:
        r.append("| ID | fromColumn | toColumn | Motivo |")
        r.append("|----|------------|----------|--------|")
        for rel in rels_removidos:
            r.append(f"| {rel['id']} | {rel['from_col']} | {rel['to_col']} | {rel['motivo']} |")
    else:
        r.append("_Nenhum relacionamento removido._")
    r.append("")
    r.append("---")
    r.append("")
    r.append("## Proteções Aplicadas (Não Removidos Apesar de \"Não utilizada\")")
    r.append("")
    if protegidos:
        r.append("| Tabela | Tipo | Nome | Motivo |")
        r.append("|--------|------|------|--------|")
        for p in sorted(protegidos, key=lambda x: (x["table"], x["tipo"], x["name"])):
            r.append(f"| {p['table']} | {p['tipo']} | {p['name']} | {p['motivo']} |")
    else:
        r.append("_Nenhum objeto protegido._")
    r.append("")
    r.append("---")
    r.append("")
    r.append("## Instruções Pós-Higienização")
    r.append("")
    r.append(f"1. Abrir `{project_name_hig}.pbip` no Power BI Desktop")
    r.append("2. Verificar se todos os visuais carregam corretamente")
    r.append("3. Revisar este relatório para confirmar que as remoções são esperadas")
    r.append("4. Se houver problemas, restaurar do projeto original e ajustar proteções")
    r.append("")

    with open(rel_path, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(r))

    return rel_path


# ==================== MAIN ====================

def encontrar_projetos_pbip(root: Path) -> List[Dict]:
    """
    Encontra todos os projetos PBIP na pasta.
    Um projeto = conjunto de .SemanticModel + .Report (com mesmo prefixo).
    Retorna lista de dicts: {name, semantic_model_dir, report_dir, pbip_file}
    """
    projetos = []
    semantic_models = {}

    for item in sorted(os.listdir(root)):
        full = root / item
        if "_higienizado" in item or "_auditoria" in item:
            continue
        if item.endswith(".SemanticModel") and full.is_dir():
            name = item.replace(".SemanticModel", "")
            semantic_models[name] = full

    for name, sm_dir in semantic_models.items():
        report_dir = root / (name + ".Report")
        pbip_file = root / (name + ".pbip")

        if report_dir.is_dir():
            projetos.append({
                "name": name,
                "semantic_model_dir": sm_dir,
                "report_dir": report_dir,
                "pbip_file": pbip_file if pbip_file.exists() else None,
            })

    return projetos


def processar_projeto(projeto: Dict, project_root: Path, dry_run: bool, modo_auditoria: bool = False, no_cache: bool = False) -> Dict:
    """
    Processa um único projeto PBIP.
    Retorna dict com estatísticas do processamento.
    """
    project_name = projeto["name"]
    semantic_model_dir = projeto["semantic_model_dir"]
    report_dir = projeto["report_dir"]
    pbip_file = projeto["pbip_file"]

    project_name_hig = project_name + ("_auditoria" if modo_auditoria else "_higienizado")

    print("=" * 60)
    print(f"HIGIENIZAÇÃO: {project_name}")
    print("=" * 60)
    print(f"SemanticModel: {semantic_model_dir.name}")
    print(f"Report: {report_dir.name}")
    if dry_run:
        print(">>> MODO DRY-RUN: nada será escrito <<<")
    print()

    tables_dir = semantic_model_dir / "definition" / "tables"

    # ETAPA 1: Extração
    print("[1/7] Extraindo objetos do modelo...")
    objetos, tabelas_info = extrair_objetos(tables_dir)
    print(f"  Total: {len(objetos)} objetos em {len(tabelas_info)} tabelas")

    # ETAPA 2: Dependências
    print("[2/7] Analisando dependências DAX...")
    uses_of, used_by = analisar_dependencias(objetos)

    # ETAPA 3: Relatório
    print("[3/7] Analisando referências no relatório...")
    referencias_visuais, paginas_por_objeto = analisar_relatorio(report_dir)

    # ETAPA 4: Classificação
    print("[4/7] Classificando objetos...")
    status_final, uso_efetivo = classificar_objetos(objetos, referencias_visuais, uses_of, used_by)
    qtd_utilizada = sum(1 for v in status_final.values() if v == "Utilizada")
    qtd_nao_utilizada = sum(1 for v in status_final.values() if v == "Não utilizada")
    print(f"  Utilizada: {qtd_utilizada} | Não utilizada: {qtd_nao_utilizada}")

    # ETAPA 5: Filtro de remoção
    para_remover = set()
    for o in objetos:
        chave = (o["table"], o["name"])
        if status_final.get(chave) == "Não utilizada":
            para_remover.add((o["table"], o["name"], o["tipo"]))

    # ETAPA 6: Proteções
    print("[5/7] Aplicando proteções...")
    para_remover, protegidos = aplicar_protecoes(para_remover)
    print(f"  Protegidos: {len(protegidos)} | Para remover: {len(para_remover)}")

    resultado = {
        "name": project_name,
        "total_objetos": len(objetos),
        "para_remover": len(para_remover),
        "protegidos": len(protegidos),
        "tabelas_removidas": 0,
        "objetos_removidos": 0,
        "dry_run": dry_run,
    }

    if dry_run:
        print(f"\n  [DRY-RUN] {project_name}: {len(para_remover)} objetos seriam removidos")
        return resultado

    # ETAPA 7: Cópia e limpeza
    print("[6/7] Copiando estrutura PBIP...")
    semantic_model_dir_hig = project_root / (project_name_hig + ".SemanticModel")
    report_dir_hig = project_root / (project_name_hig + ".Report")
    pbip_file_hig = project_root / (project_name_hig + ".pbip")

    for d in [semantic_model_dir_hig, report_dir_hig]:
        if d.exists():
            shutil.rmtree(d)

    shutil.copytree(semantic_model_dir, semantic_model_dir_hig)
    shutil.copytree(report_dir, report_dir_hig)

    # Corrigir definition.pbir para apontar para o SemanticModel higienizado
    pbir_path = report_dir_hig / "definition.pbir"
    if pbir_path.exists():
        pbir_text = pbir_path.read_text(encoding="utf-8")
        # Substituir referência do SemanticModel original pelo higienizado
        old_ref = f"../{project_name}.SemanticModel"
        new_ref = f"../{project_name_hig}.SemanticModel"
        if old_ref in pbir_text:
            pbir_text = pbir_text.replace(old_ref, new_ref)
            pbir_path.write_text(pbir_text, encoding="utf-8")
            print(f"    definition.pbir atualizado: {new_ref}")

    if pbip_file and pbip_file.exists():
        shutil.copy2(pbip_file, pbip_file_hig)
        # Corrigir .pbip para apontar para os folders higienizados
        pbip_text = pbip_file_hig.read_text(encoding="utf-8")
        old_report = f"{project_name}.Report"
        new_report = f"{project_name_hig}.Report"
        if old_report in pbip_text:
            pbip_text = pbip_text.replace(old_report, new_report)
            pbip_file_hig.write_text(pbip_text, encoding="utf-8")
            print(f"    {pbip_file_hig.name} atualizado: {new_report}")

    print("[7/7] Higienizando arquivos...")
    tables_dir_hig = semantic_model_dir_hig / "definition" / "tables"
    
    # No modo auditoria, não remover objetos
    if modo_auditoria:
        print("  [MODO AUDITORIA] Nenhum objeto será removido")
        tabelas_removidas = []
        objetos_removidos = []
        rels_removidos = []
    else:
        tabelas_removidas, objetos_removidos = higienizar_tmdl(tables_dir_hig, para_remover)

        rel_file_hig = semantic_model_dir_hig / "definition" / "relationships.tmdl"
        rels_removidos, _ = higienizar_relationships(rel_file_hig, tabelas_removidas, objetos_removidos)

        model_file_hig = semantic_model_dir_hig / "definition" / "model.tmdl"
        higienizar_model(model_file_hig, tabelas_removidas)

    # Componentes de Higienização
    print("  Criando componentes de Higienização...")
    csv_hig_path = semantic_model_dir_hig / f"levantamento_uso_objetos_{project_name}.csv"
    injetar_componentes_higienizacao(
        semantic_model_dir_hig,
        report_dir,
        report_dir_hig,
        csv_hig_path,
        project_name,
        objetos,
        status_final,
        referencias_visuais,
        used_by,
        paginas_por_objeto,
        objetos_removidos,
        tabelas_removidas,
        para_remover,
        protegidos,
        modo_auditoria,
        no_cache,
    )

    # Relatório
    relatorio_path = semantic_model_dir_hig / "RELATORIO_HIGIENIZACAO.md"
    gerar_relatorio(
        relatorio_path,
        project_name,
        project_name_hig,
        objetos,
        status_final,
        tabelas_removidas,
        objetos_removidos,
        rels_removidos,
        protegidos,
    )

    resultado["tabelas_removidas"] = len(tabelas_removidas)
    resultado["objetos_removidos"] = len(objetos_removidos)

    print(f"\n  Concluído: {project_name_hig}")
    print(f"    Tabelas removidas: {len(tabelas_removidas)}")
    print(f"    Objetos removidos: {len(objetos_removidos)}")

    return resultado


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Higienização PBIP: processa múltiplos projetos PBIP, removendo objetos não utilizados."
    )
    parser.add_argument(
        "--root",
        default=".",
        help="Pasta raiz contendo os projetos PBIP. Default: pasta atual.",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Apenas simula e mostra o que seria removido, sem escrever arquivos.",
    )
    parser.add_argument(
        "--projeto",
        default=None,
        help="Processar apenas um projeto específico (nome sem extensão).",
    )
    parser.add_argument(
        "--auditoria",
        action="store_true",
        help="Modo auditoria: apenas analisa, não remove objetos. Página com altura 1850, sem dados pós-limpeza.",
    )
    parser.add_argument(
        "--no-cache",
        action="store_true",
        help="Deleta o cache .abf após a geração para forçar reload no Power BI.",
    )
    args = parser.parse_args()

    project_root = Path(args.root).resolve()
    dry_run = args.dry_run
    modo_auditoria = args.auditoria
    no_cache = args.no_cache

    # Encontrar todos os projetos PBIP
    projetos = encontrar_projetos_pbip(project_root)

    if not projetos:
        print(f"ERRO: Nenhum projeto PBIP encontrado em: {project_root}")
        return 1

    # Filtrar por projeto específico se solicitado
    if args.projeto:
        projetos = [p for p in projetos if p["name"] == args.projeto]
        if not projetos:
            print(f"ERRO: Projeto '{args.projeto}' não encontrado.")
            return 1

    print("=" * 60)
    print("HIGIENIZAÇÃO PBIP - PROCESSAMENTO EM LOTE")
    print("=" * 60)
    print(f"Raiz: {project_root}")
    print(f"Projetos encontrados: {len(projetos)}")
    for p in projetos:
        print(f"  - {p['name']}")
    if dry_run:
        print(">>> MODO DRY-RUN: nada será escrito <<<")
    print()

    # Processar cada projeto
    resultados = []
    for i, projeto in enumerate(projetos, 1):
        print(f"\n{'#' * 60}")
        print(f"# PROJETO {i}/{len(projetos)}")
        print(f"{'#' * 60}\n")

        resultado = processar_projeto(projeto, project_root, dry_run, modo_auditoria, no_cache)
        resultados.append(resultado)

    # Resumo final
    print("\n" + "=" * 60)
    print("RESUMO FINAL - TODOS OS PROJETOS")
    print("=" * 60)
    print()
    if modo_auditoria:
        print(f"{'Projeto':<40} {'Objetos':>8} {'Identificados':>12} {'Protegidos':>10}")
    else:
        print(f"{'Projeto':<40} {'Objetos':>8} {'Removidos':>10} {'Protegidos':>10}")
    print("-" * 70)
    for r in resultados:
        status = " (dry-run)" if r["dry_run"] else ""
        removidos = r.get("objetos_removidos", r["para_remover"]) if not modo_auditoria else r["para_remover"]
        print(f"{r['name']:<40} {r['total_objetos']:>8} {removidos:>10} {r['protegidos']:>10}{status}")
    print("-" * 70)
    total_obj = sum(r["total_objetos"] for r in resultados)
    total_rem = sum(r.get("objetos_removidos", r["para_remover"]) if not modo_auditoria else r["para_remover"] for r in resultados)
    total_prot = sum(r["protegidos"] for r in resultados)
    print(f"{'TOTAL':<40} {total_obj:>8} {total_rem:>10} {total_prot:>10}")
    print()

    if not dry_run:
        modo_nome = "auditoria" if modo_auditoria else "higienizado"
        print(f"Projetos processados ({modo_nome}):")
        for r in resultados:
            print(f"  - {r['name']}_{modo_nome}")
        print()
        print("Próximos passos:")
        modo_nome = "auditoria" if modo_auditoria else "higienizado"
        print(f"  1. Abrir cada *_{modo_nome}.pbip no Power BI Desktop")
        print(f"  2. Verificar a página {'Auditoria' if modo_auditoria else 'Higienização'} em cada projeto")
        print("  3. Revisar RELATORIO_HIGIENIZACAO.md em cada SemanticModel")

    return 0


if __name__ == '__main__':
    raise SystemExit(main())
